15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    OwnerDto toOwnerDto(Owner owner);
22	
23	    Owner toOwner(OwnerDto ownerDto);
24	
25	    @Mapping(target = "id", ignore = true)
26	    @Mapping(target = "pets", ignore = true)
27	    Owner toOwner(OwnerFieldsDto ownerDto);
28	
29	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
30	
31	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
32	
33	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
34	        OwnerPageDto ownerPageDto = new OwnerPageDto();
35	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
36	        ownerPageDto.setPage(ownerPage.getNumber());
37	        ownerPageDto.setSize(ownerPage.getSize());
38	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
39	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
40	        return ownerPageDto;
41	    }
42	}
