28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date", columnDefinition = "DATE")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "membership_number")
60	    private Integer membershipNumber;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @Column(name = "membership_tier")
66	    private String membershipTier;
67	
68	    @Column(name = "namesake_count")
69	    private Integer namesakeCount;
70	
71	    @Column(name = "shares_household")
72	    private Boolean sharesHousehold;
73	
74	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
75	    private Set<Pet> pets;
76	
77	    public String getAddress() {
78	        return this.address;
79	    }
80	
81	    public void setAddress(String address) {
82	        this.address = address;
83	    }
84	
85	    public String getCity() {
86	        return this.city;
87	    }
88	
89	    public void setCity(String city) {
90	        this.city = city;
91	    }
92	
93	    public String getTelephone() {
94	        return this.telephone;
95	    }
96	
97	    public void setTelephone(String telephone) {
98	        this.telephone = telephone;
99	    }
100	
101	    public String getEmail() {
102	        return this.email;
103	    }
104	
105	    public void setEmail(String email) {
106	        this.email = email;
107	    }
108	
109	    public LocalDate getRegistrationDate() {
110	        return this.registrationDate;
111	    }
112	
113	    public void setRegistrationDate(LocalDate registrationDate) {
114	        this.registrationDate = registrationDate;
115	    }
116	
117	    public Integer getMembershipNumber() {
118	        return this.membershipNumber;
119	    }
120	
121	    public void setMembershipNumber(Integer membershipNumber) {
122	        this.membershipNumber = membershipNumber;
123	    }
124	
125	    public String getCustomerCode() {
126	        return this.customerCode;
127	    }
128	
129	    public void setCustomerCode(String customerCode) {
130	        this.customerCode = customerCode;
131	    }
132	
133	    public String getMembershipTier() {
134	        return this.membershipTier;
135	    }
136	
137	    public void setMembershipTier(String membershipTier) {
138	        this.membershipTier = membershipTier;
139	    }
140	
141	    public Integer getNamesakeCount() {
142	        return this.namesakeCount;
143	    }
144	
145	    public void setNamesakeCount(Integer namesakeCount) {
146	        this.namesakeCount = namesakeCount;
147	    }
148	
149	    public Boolean getSharesHousehold() {
150	        return this.sharesHousehold;
151	    }
152	
153	    public void setSharesHousehold(Boolean sharesHousehold) {
154	        this.sharesHousehold = sharesHousehold;
155	    }
156	
157	    protected Set<Pet> getPetsInternal() {
158	        if (this.pets == null) {
159	            this.pets = new HashSet<>();
160	        }
161	        return this.pets;
162	    }
163	
164	    protected void setPetsInternal(Set<Pet> pets) {
165	        this.pets = pets;
166	    }
167	
168	    public List<Pet> getPets() {
169	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
170	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
171	        return Collections.unmodifiableList(sortedPets);
172	    }
173	
174	    public void setPets(List<Pet> pets) {
175	        this.pets = new HashSet<>(pets);
176	    }
177	
178	    public void addPet(Pet pet) {
179	        getPetsInternal().add(pet);
180	        pet.setOwner(this);
181	    }
182	
183	    /**
184	     * Return the Pet with the given name, or null if none found for this Owner.
185	     *
186	     * @param name to test
187	     * @return true if pet name is already in use
188	     */
189	    public Pet getPet(String name) {
190	        return getPet(name, false);
191	    }
192	
193	    /**
194	     * Return the Pet with the given name, or null if none found for this Owner.
195	     *
196	     * @param name to test
197	     * @return true if pet name is already in use
198	     */
199	    public Pet getPet(String name, boolean ignoreNew) {
200	        name = name.toLowerCase();
201	        for (Pet pet : getPetsInternal()) {
202	            if (!ignoreNew || !pet.isNew()) {
203	                String compName = pet.getName();
204	                compName = compName.toLowerCase();
205	                if (compName.equals(name)) {
206	                    return pet;
207	                }
208	            }
209	        }
210	        return null;
211	    }
212	
213	    public Pet getPet(Integer petId) {
214	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
215	    }
216	
217	    /**
218	     * Return the display name of this owner, formatted as 'LastName, FirstName'.
219	     *
220	     * @return the formatted display name
221	     */
222	    @Transient
223	    public String getDisplayName() {
224	        return this.getLastName() + ", " + this.getFirstName();
225	    }
226	
227	    /**
228	     * Return the initials of this owner, being the first letter of the first and
229	     * last name, upper-cased and dot-separated with a trailing dot, e.g. 'J.S.'.
230	     *
231	     * @return the formatted initials
232	     */
233	    @Transient
234	    public String getInitials() {
235	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
236	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
237	    }
238	
239	    @Override
240	    public String toString() {
241	        return new ToStringCreator(this)
242	
243	            .append("id", this.getId())
244	            .append("new", this.isNew())
245	            .append("lastName", this.getLastName())
246	            .append("firstName", this.getFirstName())
247	            .append("address", this.address)
248	            .append("city", this.city)
249	            .append("telephone", this.telephone)
250	            .toString();
251	    }
252	}
