235	    @Override
236	    @Transactional
237	    public void saveOwner(Owner owner) throws DataAccessException {
238	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
239	        if (owner.isNew()) {
240	            if (hasIdenticalOwner(owner)) {
241	                throw new DuplicateOwnerException();
242	            }
243	            if (hasOwnerWithSameEmail(owner)) {
244	                throw new DuplicateOwnerException("An owner with the same email address already exists");
245	            }
246	            if (hasReachedDailyRegistrationLimit()) {
247	                throw new DailyOwnerRegistrationLimitExceededException();
248	            }
249	            if (hasReachedCityLimit(owner)) {
250	                throw new CityOwnerLimitExceededException();
251	            }
252	            if (owner.getRegistrationDate() == null) {
253	                owner.setRegistrationDate(LocalDate.now());
254	            }
255	            owner.setCity(resolveCity(owner));
256	            owner.setMembershipNumber(ownerRepository.findAll().size() + 1);
257	            owner.setCustomerCode(generateCustomerCode(owner));
258	            owner.setMembershipTier(resolveMembershipTier());
259	            owner.setNamesakeCount(countNamesakes(owner));
260	            owner.setSharesHousehold(sharesHousehold(owner));
261	        }
262	        ownerRepository.save(owner);
263	
264	    }
265	
266	    /**
267	     * Generates a customer code for a newly registered owner, formatted as
268	     * {@code <UPPERCASE_CITY>-<NNNN>} where {@code NNNN} is one more than the number
269	     * of owners already in that city, zero-padded to four digits (e.g. {@code LONDON-0007}).
270	     */
271	    private String generateCustomerCode(Owner owner) {
272	        String city = owner.getCity();
273	        long existingInCity = ownerRepository.findAll().stream()
274	            .filter(existing -> Objects.equals(normalize(existing.getCity()), normalize(city)))
275	            .count();
276	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), existingInCity + 1);
277	    }
278	
279	    /**
280	     * Resolves the city to store for a newly registered owner. If another owner already
281	     * lives in the same city (ignoring letter case and surrounding/repeated whitespace),
282	     * that owner's exact spelling of the city name is reused so a city is stored
283	     * consistently. Otherwise the supplied city is title-cased, i.e. each word is
284	     * capitalized and the remaining letters lower-cased (e.g. {@code "new york"} becomes
285	     * {@code "New York"}). Returns {@code null} for a {@code null} input.
286	     */
287	    private String resolveCity(Owner owner) {
288	        String city = owner.getCity();
289	        if (city == null) {
290	            return null;
291	        }
292	        String normalized = normalize(city);
293	        return ownerRepository.findAll().stream()
294	            .map(Owner::getCity)
295	            .filter(existing -> Objects.equals(normalize(existing), normalized))
296	            .findFirst()
297	            .orElseGet(() -> toTitleCase(city));
298	    }
299	
300	    /**
301	     * Title-cases a value by trimming and collapsing whitespace, then capitalizing the
302	     * first letter of each whitespace-separated word and lower-casing the rest
303	     * (e.g. {@code "  new   YORK "} becomes {@code "New York"}).
304	     */
305	    private static String toTitleCase(String value) {
306	        String collapsed = value.trim().replaceAll("\\s+", " ");
307	        if (collapsed.isEmpty()) {
308	            return collapsed;
309	        }
310	        StringBuilder result = new StringBuilder(collapsed.length());
311	        for (String word : collapsed.split(" ")) {
312	            if (result.length() > 0) {
313	                result.append(' ');
314	            }
315	            result.append(Character.toUpperCase(word.charAt(0)))
316	                .append(word.substring(1).toLowerCase(Locale.ROOT));
317	        }
318	        return result.toString();
319	    }
320	
321	    /**
322	     * The number of owners that receive the founding membership tier. The first
323	     * {@link #FOUNDING_TIER_LIMIT} owners ever created are {@code FOUNDING}; all later
324	     * owners are {@code STANDARD}.
325	     */
326	    private static final long FOUNDING_TIER_LIMIT = 100;
327	
328	    /**
329	     * Resolves the membership tier for a newly registered owner: {@code FOUNDING} while
330	     * fewer than {@link #FOUNDING_TIER_LIMIT} owners exist beforehand, otherwise {@code STANDARD}.
331	     */
332	    private String resolveMembershipTier() {
333	        return ownerRepository.findAll().size() < FOUNDING_TIER_LIMIT ? "FOUNDING" : "STANDARD";
334	    }
335	
336	    /**
337	     * Counts how many other owners already share the newly registered owner's last name,
338	     * ignoring letter case and surrounding/repeated whitespace. Invoked before the owner
339	     * is persisted, so it reflects the number of namesakes existing at creation time.
340	     */
341	    private int countNamesakes(Owner owner) {
342	        String lastName = normalize(owner.getLastName());
343	        return (int) ownerRepository.findAll().stream()
344	            .filter(existing -> Objects.equals(normalize(existing.getLastName()), lastName))
345	            .count();
346	    }
347	
348	    /**
349	     * Determines whether the newly registered owner shares a household with an existing owner,
350	     * i.e. another owner already has the same address and city (each compared ignoring letter
351	     * case and surrounding/repeated whitespace). Invoked before the owner is persisted, so it
352	     * reflects the state at creation time.
353	     */
354	    private boolean sharesHousehold(Owner owner) {
355	        String address = normalize(owner.getAddress());
356	        String city = normalize(owner.getCity());
357	        return ownerRepository.findAll().stream()
358	            .anyMatch(existing -> Objects.equals(normalize(existing.getAddress()), address)
359	                && Objects.equals(normalize(existing.getCity()), city));
360	    }
361	
362	    /**
363	     * The maximum number of owners that may be registered on a single day (by registration date).
364	     */
365	    private static final long MAX_OWNERS_PER_DAY = 20;
366	
367	    /**
368	     * Returns {@code true} if the number of owners already registered today (by registration date)
369	     * has reached {@link #MAX_OWNERS_PER_DAY}, so that no further owner may be created today.
370	     */
371	    private boolean hasReachedDailyRegistrationLimit() {
372	        LocalDate today = LocalDate.now();
373	        long registeredToday = ownerRepository.findAll().stream()
374	            .filter(existing -> today.equals(existing.getRegistrationDate()))
375	            .count();
376	        return registeredToday >= MAX_OWNERS_PER_DAY;
377	    }
378	
379	    /**
380	     * The maximum number of owners that may live in a single city.
381	     */
382	    private static final long MAX_OWNERS_PER_CITY = 8;
383	
384	    /**
385	     * Returns {@code true} if the owner's city (compared ignoring letter case and surrounding/repeated
386	     * whitespace) already contains {@link #MAX_OWNERS_PER_CITY} owners, so that no further owner may be
387	     * registered in that city.
388	     */
389	    private boolean hasReachedCityLimit(Owner owner) {
390	        String city = normalize(owner.getCity());
391	        if (city == null) {
392	            return false;
393	        }
394	        long ownersInCity = ownerRepository.findAll().stream()
395	            .filter(existing -> Objects.equals(normalize(existing.getCity()), city))
396	            .count();
397	        return ownersInCity >= MAX_OWNERS_PER_CITY;
398	    }
399	
400	    private boolean hasIdenticalOwner(Owner owner) {
401	        return ownerRepository.findAll().stream()
402	            .anyMatch(existing -> isSameOwner(existing, owner));
403	    }
404	
405	    private boolean isSameOwner(Owner existing, Owner owner) {
406	        return Objects.equals(normalizeTelephone(existing.getTelephone()), normalizeTelephone(owner.getTelephone()));
407	    }
408	
409	    /**
410	     * Normalizes a telephone number for storage and duplicate detection by stripping
411	     * everything except digits (e.g. spaces, dashes and parentheses), so that
412	     * {@code "(613) 555-0100"} and {@code "6135550100"} are treated as the same number.
413	     * Returns {@code null} for a {@code null} input.
414	     */
415	    private static String normalizeTelephone(String telephone) {
416	        if (telephone == null) {
417	            return null;
418	        }
419	        return telephone.replaceAll("[^0-9]", "");
420	    }
421	
422	    private boolean hasOwnerWithSameEmail(Owner owner) {
423	        String email = normalize(owner.getEmail());
424	        if (email == null || email.isEmpty()) {
425	            return false;
426	        }
427	        return ownerRepository.findAll().stream()
428	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
429	    }
430	
431	    /**
432	     * Normalizes a value for duplicate detection so that values differing only in
433	     * letter case or in surrounding/repeated whitespace compare as equal. Surrounding
434	     * whitespace is trimmed, internal whitespace runs are collapsed to a single space,
435	     * and the result is lower-cased (e.g. {@code "  john   smith "} and {@code "John Smith"}
436	     * both normalize to {@code "john smith"}). Returns {@code null} for a {@code null} input.
437	     */
438	    private static String normalize(String value) {
439	        if (value == null) {
440	            return null;
441	        }
442	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
443	    }
